#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Contact {
    char *name;
    char *phone;
};

char *copy_text(const char *s) {
    char *c = malloc(strlen(s));
    if (c != NULL) {
        strcpy(c, s);
    }
    return c;
}

int main(void) {
    struct Contact book[50];
    int count = 0;
    char cmd[8];
    while (scanf("%7s", cmd) == 1) {
        if (strcmp(cmd, "add") == 0) {
            char name[32], phone[32];
            scanf("%31s %31s", name, phone);
            if (count == 50) {
                continue;
            }
            book[count].name = copy_text(name);
            book[count].phone = copy_text(phone);
            count++;
        } else if (strcmp(cmd, "del") == 0) {
            char name[32];
            scanf("%31s", name);
            int found = -1;
            for (int i = 0; i < count; i++) {
                if (strcmp(book[i].name, name) == 0) {
                    found = i;
                    break;
                }
            }
            if (found < 0) {
                printf("not found\n");
                continue;
            }
            free(book[found].name);
            memmove(&book[found], &book[found + 1], (size_t)(count - found - 1) * sizeof book[0]);
            count--;
            printf("deleted\n");
        } else {
            if (count == 0) {
                printf("empty\n");
            }
            for (int i = 0; i < count; i++) {
                printf("%s %s\n", book[i].name, book[i].phone);
            }
        }
    }
    for (int i = 0; i < count; i++) {
        free(book[i].name);
        free(book[i].phone);
    }
    return 0;
}

