#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int capacity;
    scanf("%d", &capacity);
    int *items = malloc((size_t)capacity * sizeof *items);
    if (items == NULL) {
        return 1;
    }
    int head = 0, size = 0;
    char cmd[8];
    while (scanf("%7s", cmd) == 1) {
        if (strcmp(cmd, "push") == 0) {
            int x;
            scanf("%d", &x);
            int tail = (head + size) % (capacity + 1);
            items[tail] = x;
            if (size == capacity) {
                head = (head + 1) % (capacity + 1);
            } else {
                size++;
            }
        } else if (strcmp(cmd, "pop") == 0) {
            if (size == 0) {
                printf("empty\n");
            } else {
                printf("%d\n", items[head]);
                head = (head + 1) % (capacity + 1);
                size--;
            }
        } else {
            printf("%d\n", size);
        }
    }
    free(items);
    return 0;
}

